import { createServer } from './lib/api'
import { formatTotal } from './lib/format'

export interface Order {
  id: string
  items: { sku: string; qty: number; price: number }[]
  coupon?: string
  // Applied by the OAuth checkout flow.
  customerId?: string
}

/** Sum of line items before discounts and tax. */
export function subtotal(order: Order): number {
  return order.items.reduce((sum, i) => sum + i.qty * i.price, 0)
}

export async function checkout(order: Order, token: string) {
  const total = subtotal(order)
  const server = createServer({ token })
  const res = await server.post('/checkout', { id: order.id, total, customer: order.customerId })
  if (!res.ok) throw new Error(`checkout failed: ${res.status}`)
  return formatTotal(total)
}

